using Microsoft.AspNetCore.Mvc; using NotasMVC.Models; namespace NotasMVC.Controllers; public class NotaController:Controller{static List<Aluno> alunos=new(){new Aluno{Id=1,Nome="Ana",Curso="DS",Nota1=8,Nota2=7,Nota3=9}, new Aluno{Id=2,Nome="Bruno",Curso="DS",Nota1=5,Nota2=5,Nota3=6}, new Aluno{Id=3,Nome="Carla",Curso="ADM",Nota1=3,Nota2=4,Nota3=3}, new Aluno{Id=4,Nome="Diego",Curso="DS",Nota1=9,Nota2=8,Nota3=10}, new Aluno{Id=5,Nome="Eduarda",Curso="ADM",Nota1=4,Nota2=5,Nota3=4}, new Aluno{Id=6,Nome="Felipe",Curso="DS",Nota1=6,Nota2=6,Nota3=6}, new Aluno{Id=7,Nome="Giovana",Curso="ADM",Nota1=2,Nota2=3,Nota3=4}, new Aluno{Id=8,Nome="Henrique",Curso="DS",Nota1=7,Nota2=8,Nota3=7}, new Aluno{Id=9,Nome="Isabela",Curso="ADM",Nota1=5,Nota2=6,Nota3=5}, new Aluno{Id=10,Nome="João",Curso="DS",Nota1=9,Nota2=9,Nota3=8}}; public IActionResult Index()=>View(alunos); public IActionResult Aprovados()=>View(alunos.Where(x=>x.Media>=6)); public IActionResult Recuperacao()=>View(alunos.Where(x=>x.Media>=4&&x.Media<6)); public IActionResult Reprovados()=>View(alunos.Where(x=>x.Media<4));}